class TFMCommandResponseFilter extends TFMCommandResponse
{
    str filterName;
    str filterValue;
}

Method.Source:
public void appendToXML(XmlElement _element)
{
    XmlElement filterElement = _element.ownerDocument().createElement('filter');
    filterElement.setAttribute('name', filterName);
    filterElement.setAttribute('value', filterValue);
    _element.appendChild(filterElement);
}

public str parmFilterName(str _filterName = filterName)
{
    filterName = _filterName;
    return filterName;
}

public str parmFilterValue(str _filterValue = filterValue)
{
    filterValue = _filterValue;
    return filterValue;
}
